insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Apertura$vn$), $vn$OPENES-001$vn$, $vn$Greeting$vn$, $vn$Hola, ¿puedo hablar con (Nombre del Cliente)?$vn$, array[]::text[], $vn$[{"tone": "", "text": "Hola, ¿puedo hablar con (Nombre del Cliente)?"}]$vn$::jsonb, null, null, null, 10, $vn$Bright and clean. Sound like you expected them to answer.$vn$, $vn$This is a professional, confident call.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Apertura$vn$), $vn$OPENES-002$vn$, $vn$Introduction$vn$, $vn$Hola (Nombre del Cliente), ¡Feliz Día de la Semana! Mi nombre es ___, de Lionside Financial, te llamo por la solicitud que enviaste, ¿es un buen momento para hablar?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Hola (Nombre del Cliente), ¡Feliz Día de la Semana! Mi nombre es ___, de Lionside Financial, te llamo por la solicitud que enviaste, ¿es un buen momento para hablar?"}]$vn$::jsonb, null, null, null, 20, $vn$Upbeat on the greeting, grounded certainty through the introduction, then soften into RM on the final question so it does not sound scripted.$vn$, $vn$They know who this is, why they called, and it feels easy.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Apertura$vn$), $vn$OPENES-003$vn$, $vn$Recording Disclosure$vn$, $vn$Para fines de capacitación y control de calidad, esta llamada será grabada, ¿ok?$vn$, array[$vn$PT$vn$]::text[], $vn$[{"tone": "PT", "text": "Para fines de capacitación y control de calidad, esta llamada será grabada, ¿ok?"}]$vn$::jsonb, null, null, null, 30, $vn$Keep it rhythmic. The second it sounds like legal monotone, they brace.$vn$, $vn$This is routine.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La dificultad$vn$), $vn$DISCES-001$vn$, $vn$Debt and Goal Confirmation$vn$, $vn$Veo que tienes aproximadamente $XXX en deuda total no garantizada y estás pagando $XXX al mes, ¿es correcto? ¿Qué es lo que buscas lograr? ¿Bajar tu pago? ¿Bajar los intereses? ¿O quizá las dos cosas?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Veo que tienes aproximadamente $XXX en deuda total no garantizada y estás pagando $XXX al mes, ¿es correcto? ¿Qué es lo que buscas lograr? ¿Bajar tu pago? ¿Bajar los intereses? ¿O quizá las dos cosas?"}]$vn$::jsonb, null, null, null, 10, $vn$Certainty on the numbers. Shift into genuine curiosity on the goal question, then stop.$vn$, $vn$He knows my situation and wants to know what I actually want.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La dificultad$vn$), $vn$DISCES-002$vn$, $vn$Set the Agenda$vn$, $vn$Nos especializamos en ofrecer soluciones financieras personalizadas para nuestros clientes. Hoy vamos a revisar juntos tus opciones para resolver la deuda y restaurar tu crédito. ¿Te parece bien?$vn$, array[$vn$AC$vn$,$vn$I CARE$vn$,$vn$RM$vn$]::text[], $vn$[{"tone": "AC", "text": "Nos especializamos en ofrecer soluciones financieras personalizadas para nuestros clientes."}, {"tone": "I CARE", "text": "Hoy vamos a revisar juntos tus opciones para resolver la deuda y restaurar tu crédito."}, {"tone": "RM", "text": "¿Te parece bien?"}]$vn$::jsonb, null, null, null, 20, $vn$Three tones in one breath: certainty, warmth, then Reasonable Man on the permission question.$vn$, $vn$I have an expert helping me and I am still in control.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La dificultad$vn$), $vn$DISCES-003$vn$, $vn$Bankruptcy Question$vn$, $vn$¿La bancarrota es algo que estás considerando?$vn$, array[$vn$I CARE$vn$]::text[], $vn$[{"tone": "I CARE", "text": "¿La bancarrota es algo que estás considerando?"}]$vn$::jsonb, null, null, null, 30, $vn$Slow. Neutral. Zero judgment. Then silence.$vn$, $vn$I can answer this honestly.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La dificultad$vn$), $vn$DISCES-004$vn$, $vn$What Happened$vn$, $vn$Eso es bueno. No parece que hayas llegado todavía al punto límite. Ahora, veo que antes tu puntaje era más alto y tenías menos deuda. Si no te molesta, ¿me puedes contar,... qué pasó?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Eso es bueno. No parece que hayas llegado todavía al punto límite. Ahora, veo que antes tu puntaje era más alto y tenías menos deuda. Si no te molesta, ¿me puedes contar,... qué pasó?"}]$vn$::jsonb, null, $vn$(Profundiza en la dificultad SLOW DOWN)$vn$, null, 40, $vn$Energy drops steadily across this one. Real silence before "what happened", then stop talking completely.$vn$, $vn$He genuinely wants to understand what happened to me.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La dificultad$vn$), $vn$DISCES-005$vn$, $vn$Sample Questions$vn$, $vn$¿Cuánto tiempo lleva pasando esto? ¿Por lo menos puedes mantenerte al día con tus gastos básicos? ¿Qué vas a hacer si esto no mejora? ¿Cómo está afectando a tu familia? ¿Cómo está afectando tu salud?$vn$, array[]::text[], $vn$[{"tone": "", "text": "¿Cuánto tiempo lleva pasando esto? ¿Por lo menos puedes mantenerte al día con tus gastos básicos? ¿Qué vas a hacer si esto no mejora? ¿Cómo está afectando a tu familia? ¿Cómo está afectando tu salud?"}]$vn$::jsonb, null, $vn$Preguntas de ejemplo. (Resume lo que te dijeron y demuestra empatía, para que sepan que estabas escuchando)$vn$, null, 50, $vn$One question at a time. Never stack them. Let each answer land before the next.$vn$, $vn$He is listening, not interviewing me.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Crear al villano$vn$), $vn$VILLES-001$vn$, $vn$Empathy Bridge$vn$, $vn$Gracias por compartir eso conmigo… desafortunadamente, no eres el único.$vn$, array[$vn$I CARE$vn$]::text[], $vn$[{"tone": "I CARE", "text": "Gracias por compartir eso conmigo… desafortunadamente, no eres el único."}]$vn$::jsonb, null, null, null, 10, $vn$Quiet. Unhurried. This is the pivot point of the whole call.$vn$, $vn$I was heard.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Crear al villano$vn$), $vn$VILLES-002$vn$, $vn$The Preacher$vn$, $vn$Millones de estadounidenses viven de cheque en cheque, y basta con que pase una sola cosa para realmente atrasarnos. Lo que mucha gente no se da cuenta es que estos acreedores se aprovechan de los consumidores. Con las tasas de interés y los pagos tan altos, nos llevan a un punto donde solamente podemos pagar los mínimos. Y entonces estamos a una sola dificultad de atrasarnos. Esos mismos acreedores normalmente son los últimos en ayudarte cuando empiezas a batallar. ¿Verdad?$vn$, array[$vn$Preacher$vn$]::text[], $vn$[{"tone": "Preacher", "text": "Millones de estadounidenses viven de cheque en cheque, y basta con que pase una sola cosa para realmente atrasarnos. Lo que mucha gente no se da cuenta es que estos acreedores se aprovechan de los consumidores. Con las tasas de interés y los pagos tan altos, nos llevan a un punto donde solamente podemos pagar los mínimos. Y entonces estamos a una sola dificultad de atrasarnos. Esos mismos acreedores normalmente son los últimos en ayudarte cuando empiezas a batallar. ¿Verdad?"}]$vn$::jsonb, null, null, null, 20, $vn$Build energy across the whole passage. Land hard on "prey on consumers". The closing question is a demand for agreement, not a real question.$vn$, $vn$This was not entirely my fault, and he is on my side.$vn$, false, 'published');
